{
  "name": "NJ FamilyCare Medicare Savings Programs",
  "eligibility": {
    "age": null,
    "income_limits": {
      "QMB": {
        "single": "$15,960/year",
        "couple": "$21,640/year"
      },
      "SLMB": {
        "single": "$19,152/year",
        "couple": "$25,968/year"
      },
      "QI-1": {
        "single": "$21,546/year",
        "couple": "$29,214/year"
      },
      "notes": [
        "These are 2026 limits shown on New Jersey official materials.",
        "The program is for people with Medicare Part A and Part B who have limited income and assets.",
        "NJ materials also describe QMB/SLMB/QI in terms of monthly Federal Poverty Guideline-style thresholds in some consumer guides, but the official New Jersey state pages give the annual limits above."
      ]
    },
    "asset_limits": {
      "single": "$9,950",
      "couple": "$14,910",
      "what_counts": [
        "Countable assets/liquid resources",
        "NJ materials describe the limit as assets/liquid assets"
      ],
      "what_is_exempt": [
        "Home",
        "Car"
      ],
      "notes": [
        "New Jersey official pages state that assets do not include the home or car.",
        "The same asset limit is shown for QMB, SLMB, and QI."
      ]
    },
    "other_requirements": [
      "Must be a New Jersey resident",
      "Must be enrolled in Medicare Part A and Part B",
      "Must not be financially eligible for NJ FamilyCare Medicaid",
      "Eligibility is based on income and assets",
      "No county-specific residency rule is described; it is statewide"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Helps pay Medicare costs. QMB can pay Medicare Part A and Part B premiums, deductibles, copayments, and coinsurance. SLMB and QI help pay the Medicare Part B premium. New Jersey consumer materials say the state can pay the Part B premium and save eligible people over $2,000 per year.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: NJSave application (official NJ.gov/NJSave route)",
      "Paper application: NJSave paper application",
      "Phone: 1-800-792-9745",
      "Help with application / phone enrollment support: 1-800-701-0710 (TTY: 711)",
      "County SHIP assistance"
    ],
    "processing_time": "No specific statewide processing time was stated in the official materials found.",
    "waitlist": null,
    "forms": [
      "NJSave application",
      "NJSave paper application"
    ],
    "documents": [
      "Proof of Medicare Part A and Part B enrollment",
      "Proof of New Jersey residency",
      "Proof of income",
      "Proof of assets/resources",
      "Identification information needed to complete the NJSave application"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available to New Jersey residents statewide; no county restriction is stated.",
    "regional_variations": "No formal benefit variation by region was described. Regional differences are mainly in where a person gets help applying, such as county SHIP assistance.",
    "offices_or_providers": [
      "County State Health Insurance Assistance Program (SHIP)",
      "NJSave / NJ FamilyCare application support lines"
    ]
  },
  "official_source": "https://www.nj.gov/humanservices/doas/services/l-p/msp/",
  "gotchas": [
    "This is not the same as full Medicaid; it is a Medicare cost-help program tied to Medicare Part A and Part B.",
    "The benefit level depends on the tier: QMB is broader and can cover deductibles/copays/coinsurance, while SLMB and QI mainly help with Part B premiums.",
    "The state pages emphasize both income and asset limits; many applicants miss the asset test.",
    "The home and car are excluded from the asset limit in the New Jersey materials found.",
    "Some New Jersey pages point people to NJSave rather than a separate Medicare Savings Program-only portal.",
    "Applicants can get help through SHIP or by calling the hotline if the online form is confusing."
  ],
  "data_shape_notes": "This program has tiered benefits by MSP category (QMB, SLMB, QI), with separate income thresholds but a shared asset test and statewide administration."
}

{
  "name": "New Jersey SSI State Supplement",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "summary": "This is not a separate NJ-only income test. It is the SSI program, with New Jersey adding a state supplement to the federal SSI payment for eligible recipients. For 2026, New Jersey says an individual may be eligible if gross monthly income is at or below $1,025.25, or $1,516.35 for a couple, with the first $20 of income excluded.[3][6]",
      "table": [
        {
          "household_type": "Individual",
          "gross_monthly_income_limit_2026": "$1,025.25",
          "notes": "First $20/month excluded in determining countable income.[3][6]"
        },
        {
          "household_type": "Couple",
          "gross_monthly_income_limit_2026": "$1,516.35",
          "notes": "First $20/month excluded in determining countable income.[6]"
        }
      ],
      "important_caveat": "SSA payment amounts vary by living arrangement and other factors, so the actual monthly SSI check can be lower than the maximum.[3][4]"
    },
    "asset_limits": {
      "individual": "$2,000",
      "couple": "$3,000",
      "what_counts": [
        "Cash and bank accounts",
        "Other countable resources used by SSA in SSI eligibility"
      ],
      "what_is_exempt": [
        "The source confirms a resource maximum but does not fully enumerate all exemptions on the retrieved pages.[6]"
      ],
      "notes": "Families should verify the full SSI resource rules with SSA before applying, because some assets are excluded under federal SSI rules even though the program uses these resource caps.[6]"
    },
    "other_requirements": [
      "Must be 65 or older, or blind, or disabled under SSA rules; New Jersey also notes age 65 or older applicants without a disability can qualify if they have little to no income or resources.[3][14]",
      "Must meet federal SSI nonfinancial rules handled by SSA",
      "Must live in a qualifying living arrangement for the applicable payment level",
      "Must be a New Jersey SSI recipient to receive the state supplement, which is paid automatically with SSI rather than through a separate NJ application.[1][4]"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "New Jersey’s state supplement is added to the federal SSI payment and is paid monthly as part of the total SSI benefit. For 2026, SSA lists these combined monthly amounts for New Jersey: living alone or with others in own household $1,025.25; living with spouse not eligible for SSI $1,146.99; living in someone else’s household and receiving support and maintenance $706.98; living in a licensed residential health care facility $1,204.05; living in a public general hospital or Medicaid-approved long-term health facility $50.00; couple living alone or with others in own household $1,475.35; couple living in someone else’s household and receiving support and maintenance $1,059.75; couple living in a licensed residential health care facility $2,188.35.[4]",
    "varies_by": "household_size"
  },
  "application": {
    "methods": [
      "Online: https://www.ssa.gov/ssi/",
      "Phone: 1-800-772-1213",
      "TTY: 1-800-325-0778",
      "In person at a local Social Security office"
    ],
    "processing_time": "The retrieved sources do not give a specific processing-time number for New Jersey SSI applications.",
    "waitlist": "No waitlist is described in the retrieved sources; SSI is administered through SSA and the New Jersey supplement is automatic for eligible SSI recipients.[1][4]",
    "forms": [
      "SSA SSI application process (online or by appointment); the retrieved pages do not name a New Jersey-specific supplement form.",
      "NJ sources point applicants to apply for SSI through SSA rather than a separate state supplement application.[2][3]"
    ],
    "documents": [
      "Identification such as a driver’s license, state ID, or passport[5]",
      "Birth certificate[5]",
      "Income information",
      "Resource/bank information",
      "Information about living arrangement and household members",
      "Any SSA disability/blindness/medical records if applicable"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide to New Jersey SSI recipients; payment level depends on living arrangement and whether the person is in a licensed residential health care facility, hospital, or lives in someone else’s household.[4]",
    "regional_variations": "No county-by-county variation was identified in the retrieved sources. The main variation is by living arrangement, not geography.[4][12]",
    "offices_or_providers": [
      "Social Security Administration offices statewide",
      "NJ Division of Disability Determination Services for SSI claims handling in New Jersey[2]"
    ]
  },
  "official_source": "https://www.ssa.gov/ssi/text-benefits-ussi.htm",
  "gotchas": [
    "Families often miss that New Jersey’s supplement is not a separate state benefit application; it is paid automatically with SSI if the person qualifies.[1][4]",
    "The payment depends heavily on living arrangement, so where the person lives can change the monthly amount.[4]",
    "Gross income limits and the actual payment amounts are not the same thing; a person can qualify but receive less than the maximum because of countable income and living situation.[3][4][6]",
    "Resource limits are strict at $2,000 for one person and $3,000 for a couple, so even modest savings can affect eligibility.[6]",
    "Some New Jersey materials also point SSI applicants to SSA phone-based or in-person application routes rather than a special NJ office process.[2][5]"
  ],
  "data_shape_notes": "This program is structured as an automatic state cash supplement layered onto federal SSI, with benefit amounts changing by living arrangement and household type rather than by county or a standalone NJ application process.[1][4]"
}
